const seen = new Set();
const articles = [];
const fromDate = new Date(Date.now() - 14 * 24 * 60 * 60 * 1000);

for (const item of $input.all()) {
  const results = item.json.results || [];
  for (const a of results) {
    if (!a.title || !a.link) continue;
    if (seen.has(a.link)) continue;
    // Filtrer articles trop anciens
    if (a.pubDate) {
      const pub = new Date(a.pubDate);
      if (!isNaN(pub.getTime()) && pub < fromDate) continue;
    }
    seen.add(a.link);
    articles.push({
      titre: (a.title || '').slice(0, 200),
      source: a.source_id || '',
      lien: a.link || '',
      date: a.pubDate || '',
      desc: (a.description || a.content || '').replace(/<[^>]+>/g, '').slice(0, 150)
    });
  }
}

// Limiter à 20 articles max pour ne pas dépasser le contexte Groq
const limited = articles.slice(0, 8);
console.log('Articles collectés:', articles.length, '| Envoyés à Groq:', limited.length);
if (limited.length === 0) return [{ json: { _empty: true } }];

const lines = limited.map((a, i) =>
  (i+1) + '. TITRE: ' + a.titre + ' | SOURCE: ' + a.source + ' | DATE: ' + a.date + ' | DESC: ' + a.desc
).join('\n\n');

const payload = {
  model: 'llama-3.3-70b-versatile',
  temperature: 0.1,
  max_tokens: 6000,
  messages: [
    {
      role: 'system',
      content: 'Analyste veille stratégique pour Attijariwafa Bank (AWB), division Paiement Multicanal Maroc. Retourne UNIQUEMENT du JSON pur sans markdown : { "articles": [...] }\n\nPour chaque article, champs OBLIGATOIRES :\n- titre, source, lien, date_publication\n- resume: 1 phrase\n- categorie: Paiement multicanal|Banque concurrente|Fintech|Régulation|Service public|E-commerce|Innovation|Partenariat|Autre\n- type_signal: Lancement produit|Partenariat|Évolution réglementaire|Initiative concurrente|Digitalisation|Opportunité marché|Tendance émergente|Information générale\n- acteurs_cites, banque_concurrente\n- importance: Élevée|Moyenne|Faible\n- opportunite: comment AWB peut en profiter concrètement (OBLIGATOIRE)\n- menace: quel risque pour AWB ou avantage concurrent (OBLIGATOIRE)\n- impact_awb: 1 phrase\n- action_recommandee: 1 action concrète pour AWB\n- score: 0-100 (0-29=non pertinent, 30-59=pertinent, 60-100=très pertinent)'
    },
    {
      role: 'user',
      content: 'Analyse ces ' + limited.length + ' articles :\n\n' + lines
    }
  ]
};

return [{ json: { payload, count: articles.length } }];

const raw = $input.first().json.choices?.[0]?.message?.content || '';
if (!raw) return [{ json: { debug: 'GROQ_NO_RESPONSE', input: JSON.stringify($input.first().json).slice(0, 300) } }];
let parsed = {};
try {
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start === -1 || end === -1) return [{ json: { debug: 'NO_JSON_IN_RESPONSE', raw: raw.slice(0, 500) } }];
  parsed = JSON.parse(raw.slice(start, end + 1));
} catch(e) {
  return [{ json: { debug: 'JSON_PARSE_ERROR', error: e.message, raw: raw.slice(0, 500) } }];
}

const articles = Array.isArray(parsed.articles) ? parsed.articles : [];
if (articles.length === 0) return [{ json: { debug: 'NO_ARTICLES_IN_JSON', raw: raw.slice(0, 500) } }];

const scores = articles.map(a => a.score);
const relevant = articles.filter(a => (Number(a.score) || 0) >= 30);
if (relevant.length === 0) return [{ json: { debug: 'ALL_SCORES_BELOW_30', total: articles.length, scores: scores.join(','), sample_titre: articles[0].titre } }];

const now = new Date();
const dateCollecte = now.toLocaleDateString('fr-FR', { day:'2-digit', month:'2-digit', year:'numeric' })
  + ' ' + now.toLocaleTimeString('fr-FR', { hour:'2-digit', minute:'2-digit' });

return relevant.map(a => ({ json: {
  'Date de collecte':   dateCollecte,
  'Titre':              String(a.titre || '').slice(0, 300),
  'Source':             String(a.source || ''),
  'Lien':               String(a.lien || ''),
  'Date publication':   String(a.date_publication || ''),
  'Résumé':             String(a.resume || '').slice(0, 500),
  'Catégorie':          String(a.categorie || 'Autre'),
  'Sous-catégorie':     String(a.impact_awb || ''),
  'Type de signal':     String(a.type_signal || ''),
  'Acteurs cités':      String(a.acteurs_cites || ''),
  'Banque concurrente': String(a.banque_concurrente || ''),
  'Importance':         String(a.importance || 'Faible'),
  'Opportunité':        String(a.opportunite || ''),
  'Menace':             String(a.menace || ''),
  'Impact pour AWB':    String(a.impact_awb || ''),
  'Action recommandée': String(a.action_recommandee || ''),
  'Pertinent':          'true',
  'Statut':             Number(a.score) >= 60 ? 'À conserver' : 'À revoir'
}}));
